$AlertsFilePath = ".\perimeter_deception_engine\deception_alerts.json"; $HoneyTokenEndpoint = "/api/v1/financial/export-ledgers"; function Write-DeceptionAlert($Target, $Type) { [System.Collections.Generic.List[PSCustomObject]]$Events = @(); if (Test-Path $AlertsFilePath) { $Content = Get-Content $AlertsFilePath -Raw; if ($Content) { $Json = ConvertFrom-Json $Content; if ($Json) { foreach ($Item in $Json) { $Events.Add($Item) } } } }; $NewAlert = [PSCustomObject]@{Timestamp = (Get-Date -Format "yyyy-MM-dd HH:mm:ss"); TargetEndpoint = $Target; IncidentType = $Type}; $Events.Add($NewAlert); $Events | ConvertTo-Json -Depth 3 | Set-Content $AlertsFilePath }; $SimulatedAccess = "/api/v1/financial/export-ledgers"; if ($SimulatedAccess -eq $HoneyTokenEndpoint) { Write-DeceptionAlert -Target $SimulatedAccess -Type "Critical_HoneyToken_Intrusion" }
